- AUDIENCIA_DECISORA: {{AUDIENCIA_DECISORA}}
- DECISION_BUSCADA: {{DECISION_BUSCADA}}
- EVIDENCIA_DISPONIBLE: {{EVIDENCIA_DISPONIBLE}}
- HORIZONTE: {{HORIZONTE}}
